#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int gcdResult, xCoeff, yCoeff;

void computeGCD(int a, int b) {
    if (b == 0) {
        gcdResult = a; xCoeff = 1; yCoeff = 0;
    } else {
        computeGCD(b, a % b);
        int temp = xCoeff - a / b * yCoeff;
        xCoeff = yCoeff;
        yCoeff = temp;
    }
}

int modularInverse(int a) {
    computeGCD(a, MOD);
    return xCoeff < 0 ? xCoeff + MOD : xCoeff;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN, totalM, totalK;
    cin >> totalN >> totalM >> totalK;
    int invM = modularInverse(totalM);
    vector<long long> dpArray(totalK + 1, 0);
    dpArray[0] = 1;

    for (int step = 0; step < totalK; step++) {
        for (int d = totalK - 1; d >= 0; d--) {
            if (dpArray[d] != 0) {
                dpArray[d + 1] = (dpArray[d + 1] + dpArray[d] * (totalN - d)) % MOD;
                dpArray[d] = (dpArray[d] * d) % MOD;
            }
        }
    }

    long long probabilityPower = 1;
    long long answer = 0;
    for (int d = 1; d <= totalK; d++) {
        probabilityPower = (probabilityPower * invM) % MOD;
        answer = (answer + dpArray[d] * probabilityPower) % MOD;
    }
    cout << answer << "\n";
    return 0;
}
